from pathlib import Path
from html import escape
scale=8
parts=['''<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="780" viewBox="0 0 1000 780"><rect width="1000" height="780" fill="#f7f6f2"/><style>text{font-family:'Hiragino Sans','Arial',sans-serif;fill:#253532}.title{font-size:27px;font-weight:700}.head{font-size:21px;font-weight:600}.small{font-size:15px}.muted{fill:#62736e}</style><text x="48" y="48" class="title">48時間録音を目指す、2つのサイズ案</text><text x="48" y="78" class="small muted">外形の設計目標を同じ縮尺で比較。実装・寿命は未検証／画面上の実寸ではありません</text>''']
for cx,d,cap,title,cell,limit in [(260,25.5,150,'A · Omiサイズを維持','16 × 5.4 mm','2.0 mA以下を目標'),(730,28,210,'B · 直径を2.5mm広げる','24 × 4.15 mm','3.0 mA以下を目標')]:
 r=d*scale/2; x=cx-r
 parts.append(f'''<text x="{cx}" y="127" text-anchor="middle" class="head">{title}</text><circle cx="{cx}" cy="270" r="{r}" fill="#dce5e0" stroke="#354c43" stroke-width="2"/><text x="{cx}" y="262" text-anchor="middle" class="head">{d:g} mm</text><text x="{cx}" y="290" text-anchor="middle" class="small muted">正面・円形</text><path d="M{x} 408H{cx+r} M{x} 401V415 M{cx+r} 401V415" stroke="#62736e"/><text x="{cx}" y="433" text-anchor="middle" class="small">直径 {d:g} mm</text><rect x="{x}" y="470" width="{r*2}" height="120" rx="13" fill="#dce5e0" stroke="#354c43" stroke-width="2"/><text x="{cx}" y="522" text-anchor="middle" class="small">側面</text><text x="{cx}" y="548" text-anchor="middle" class="head">厚さ 15 mm</text><text x="{cx}" y="632" text-anchor="middle" class="head">{cap} mAh / {limit}</text><text x="{cx}" y="660" text-anchor="middle" class="small muted">裸セル寸法：{cell}</text>''')
parts.append('''<path d="M80 715H240 M80 709V721 M160 709V721 M240 709V721" stroke="#253532" stroke-width="2"/><text x="80" y="745" class="small">0</text><text x="150" y="745" class="small">10</text><text x="225" y="745" class="small">20 mm</text><text x="350" y="720" class="small">使用可能容量70%と仮定：Aは2mAで52.5時間、Bは3mAで49時間</text><text x="350" y="746" class="small muted">セル公称値：Grepow GRP1654M1 / GRP2440R1。保護・配線は別途。</text></svg>''')
Path(__file__).with_name('size-comparison.svg').write_text(''.join(parts))
